// Entrada: item vindo do Orchestrator
const i = $json;

// ---- Parse arquivos (jsonb -> array de {url, type?}) ----
let arquivos = i.arquivos;
if (typeof arquivos === 'string') {
  try { arquivos = JSON.parse(arquivos); } catch(e) {}
}
arquivos = Array.isArray(arquivos) ? arquivos : [];

const urls = arquivos.map(a => a?.url).filter(Boolean);
const firstUrl = urls[0] || '';

// ---- Normaliza mídia/tipo ----
const midiaTipo = String(i.midia_tipo || '').toLowerCase();     // video | imagem
const postTipo  = String(i.post_tipo  || '').toLowerCase();     // unica | carrossel
const isVideo   = midiaTipo === 'video';
const isImage   = midiaTipo === 'imagem';
const isCarousel = postTipo === 'carrossel' || urls.length > 1;

// ---- Textos ----
const txt = {
  ig_fb: i.texto_instagram_facebook || '',
  youtube: i.texto_youtube || '',
  x_threads_tiktok: i.texto_x_threads_tiktok || '',
  linkedin: i.texto_linkedin || '',
};

// Shorts (YouTube): garante #shorts se for vídeo e não existir
let youtubeText = txt.youtube;
const isShorts = (i.platform === 'youtube' && isVideo);
if (isShorts && !/\#shorts\b/i.test(youtubeText)) {
  youtubeText = (youtubeText + '\n\n#shorts').trim();
}

// Helpers: título/descrição (heurística simples)
const firstLine = (s) => (String(s||'').split(/\r?\n/)[0] || '').trim();
const clip = (s, n) => String(s||'').slice(0, n);

// ---- Payload padronizado (SaaS-grade) ----
const payload = {
  meta: {
    post_id: i.post_id,
    platform: i.platform,
    idempotency_key: i.idempotency_key,
    created_at: i.created_at || null,
  },
  media: {
    type: isVideo ? 'video' : 'image',
    post_type: isCarousel ? 'carousel' : 'single',
    urls,
    first_url: firstUrl,
    count: urls.length,
  },
  content: {
    // Campos genéricos para qualquer node
    caption: (i.platform === 'instagram' || i.platform === 'facebook') ? txt.ig_fb : (
      i.platform === 'linkedin' ? txt.linkedin : txt.x_threads_tiktok
    ),
    title: i.platform === 'youtube' ? firstLine(youtubeText) : firstLine(txt.ig_fb),
    description: i.platform === 'youtube' ? youtubeText : (
      i.platform === 'tiktok' ? txt.x_threads_tiktok : ''
    ),
    hashtags: (i.platform === 'youtube') ? ['shorts'] : [],
    raw: {
      ig_fb: txt.ig_fb,
      youtube: youtubeText,
      x_threads_tiktok: txt.x_threads_tiktok,
      linkedin: txt.linkedin,
    },
  },
  platform_config: {
    instagram: {
      mediaType: isVideo ? 'REELS' : 'POST',
      isCarousel,
    },
    facebook: {
      isCarousel,
    },
    youtube: {
      isShorts,
      categoryId: '27',
      tags: ['inteligenciaartificial','chatgpt','ia','shorts'].filter(Boolean),
    },
    x: {
      maxLength: 280,
    },
    tiktok: {
      title: clip(firstLine(txt.x_threads_tiktok), 150),
      description: txt.x_threads_tiktok,
    },
    linkedin: {
      visibility: 'PUBLIC',
    },
    threads: {},
  },
};

// ---- Saídas legadas (pra facilitar mapear nos seus nodes atuais) ----
return {
  json: {
    ...i,
    arquivos,
    mediaUrl: firstUrl,
    mediaUrls: urls,
    isVideo,
    isCarousel,
    youtubeText,
    payload
  }
};
